    "question": "Şekilde Kalp kasına uyarı verilmesi sonrasında gözlenen membran potansiyeli değişimi görülmektedir. Kalp kasında gözlenen aksiyon potansiyeli ile ilgili verilen, I. A ile gösterilen dönemde Na* kanalları açıktır, depolarizasyon evresidir. II. B ile gösterilen bölge erken repolarizasyon dönemidir. Bu dönemde hücreden geçici K* çıkışı gözlenir. III.Plato döneminde (C) kalsiyumun hücre içine girmesi kontraksiyon sürecini başlatır, bu dönemde  yavaş kalsıyum kanalları açıktır. IV.Kalp kası plato döneminde mutlak refraktör dönemde, geç repolarizasyon (D) döneminin yarısına kadar olan dönemde ise rölatif refraktör dönemdedir. İfadelerinden hangisi/hangileri söylenemez?",
