    "explanation": "**Birinci kaburgada (Costa I)**, korpusu yatay durduğu ve alt kenarı bulunmadığı için interkostal damar-sinir paketinin geçtiği sulcus costae oluğu bulunmaz; oluk tipik kaburgalarda bulunur.",
