    "answer": "D",
    "open_answer": "",
    "explanation": "**Barlow ve Ortolani manevraları**, yenidoğan ve süt çocukluğu döneminde kalça ekleminin instabilitesini ve femur başının asetabulum içine girip çıkmasını test eden, gelişimsel kalça displazisi (GKD) tarama manevralarıdır.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
