    "professor": "Belirtilmemiş",
    "question": "Dirsek ekleminde ön kol ile kol arasındaki medial taşıma açısının daralması veya içe açılanması hangi terimle ifade edilir?",
    "options": [
      {
        "letter": "A",
        "text": "Cubitus valgus"
      },
      {
        "letter": "B",
        "text": "Genu valgum"
      },
      {
        "letter": "C",
        "text": "Cubitus varus"
      },
      {
        "letter": "D",
        "text": "Genu varum"
      },
      {
        "letter": "E",
        "text": "Coxa vara"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "Dirsek ekleminde önkolun koldan dışa doğru olan normal fizyolojik taşıma açısının daralarak mediale (içe) yönlenmesine **cubitus varus** adı verilir; çoğunlukla kaynamış suprakondiler kırıklar sonrası gelişir.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
    "q_type": "mcq",
    "incomplete": false,
