    "subject": "Anatomi",
    "professor": "Belirtilmemiş",
    "question": "Ayak bileği ekleminde 'Pott kırığı' ile ifade edilen kırık tipi aşağıdakilerden hangisidir?",
    "options": [
      {
        "letter": "A",
        "text": "Unimalleoler izole fibula kırığı"
      },
      {
        "letter": "B",
        "text": "Kalkaneus kompresyon kırığı"
      },
      {
        "letter": "C",
        "text": "Trimalleoler kırık"
      },
      {
        "letter": "D",
        "text": "Patella avülsiyon kırığı"
      },
      {
        "letter": "E",
        "text": "Bimalleoler kırık (lateral ve medial malleol kırığı)"
      }
    ],
    "answer": "E",
    "open_answer": "",
    "explanation": "**Pott kırığı**, ayak bileğinde şiddetli eversiyon-rotasyon travması sonucu lateral malleol (fibula distal ucu) ve medial malleolün (tibia distal ucu) birlikte kırıldığı klasik **bimalleoler kırıktır**.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
