    "year": "2018-2019",
    "q_num": 130,
    "subject": "Anatomi",
    "professor": "Belirtilmemiş",
    "question": "Nervus fibularis (peroneus) communis hasarı ve buna bağlı düşük ayak tablosu en sık aşağıdaki travmalardan hangisinde meydana gelir?",
    "options": [
      {
        "letter": "A",
        "text": "Fibulanın proksimal bölgesi ve collum fibulae kırıkları"
      },
      {
        "letter": "B",
        "text": "Ayak bileği burkulması"
      },
      {
        "letter": "C",
        "text": "Tuberositas tibiae çıkığı"
      },
      {
        "letter": "D",
        "text": "Diz eklemi fleksiyon travmaları"
      },
      {
        "letter": "E",
        "text": "Pott kırığı"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "**Nervus fibularis (peroneus) communis**, collum fibulae'yi dıştan dolanarak yüzeyelleştiği için bu bölge kırıklarında veya kompresyonlarında kolayca yaralanır ve ayak dorsifleksiyonunun kaybıyla **düşük ayak** tablosu gelişir.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
