    "explanation": "Subakromiyal sıkışma (impingement) sendromunda kolun abdüksiyonu sırasında acromion ve lig. coracoacromiale altında sıkışarak dejenerasyon ve rüptüre uğrayan ana kas tendonu **musculus supraspinatus**'tur.",
