    "open_answer": "",
    "explanation": "**Fossa digastrica**, corpus mandibulae'nin iç-alt kenarında simfizis menti yakınında simetrik olarak yer alan iki küçük çukurcuktur ve musculus digastricus venter anterior'un tutunma yeridir.",
