    "q_num": 161,
    "subject": "Anatomi",
    "professor": "Belirtilmemiş",
    "question": "Aşağıdaki kemiklerden hangisinin os zygomaticum (elmacık kemiği) ile herhangi bir eklem bağlantısı yoktur?",
    "options": [
      {
        "letter": "A",
        "text": "Os frontale"
      },
      {
        "letter": "B",
        "text": "Os ethmoidale"
      },
      {
        "letter": "C",
        "text": "Os sphenoidale"
      },
      {
        "letter": "D",
        "text": "Maxilla"
      },
      {
        "letter": "E",
        "text": "Os temporale"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "**Os zygomaticum** (elmacık kemiği); os frontale, os temporale, os sphenoidale (ala major) ve maxilla ile eklem yapar; burun boşluğu derinliğinde yer alan **os ethmoidale** ile eklem bağlantısı yoktur.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
