    "q_num": 162,
    "subject": "Anatomi",
    "professor": "Belirtilmemiş",
    "question": "Fossa pterygopalatina'yı sert damağa bağlayan canalis palatinus major hangi iki kemik arasında oluşur?",
    "options": [
      {
        "letter": "A",
        "text": "Os palatinum - Maxilla"
      },
      {
        "letter": "B",
        "text": "Os palatinum - Os sphenoidale"
      },
      {
        "letter": "C",
        "text": "Os sphenoidale - Os ethmoidale"
      },
      {
        "letter": "D",
        "text": "Os sphenoidale - Maxilla"
      },
      {
        "letter": "E",
        "text": "Os palatinum - Os ethmoidale"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "**Canalis palatinus major**, os palatinum'un lamina perpendicularis'indeki sulcus ile maxilla facies nasalis'indeki sulcus'un karşılıklı gelerek fossa pterygopalatina'yı sert damağa bağladığı kanaldır.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
