    "explanation": "**Tuberositas glutea**, femur gövdesinin arka yüzünde linea aspera'nın proksimaldeki lateral devamı olan pürtüklü sahadır ve kalçanın en güçlü ekstansör kası olan musculus gluteus maximus'un tutunduğu yerdir.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
