    "explanation": "Kompakt kemikte osteonların lameller görünümü, birbirini takip eden komşu lamellerdeki **Tip I kollajen liflerinin** birbirine zıt yönlerde ve dik açılarla sarmal uzanarak polarize ışığı farklı kırmasından kaynaklanır.",
    "note": "Cevap anahtarı tıbbi literatüre göre tamamlanmıştır.",
