    "professor": "Belirtilmemiş",
    "question": "VERTEBRA YAYLARININ AÇIKLIĞI VEYA TAM BİRLEŞMEMESİ SONUCU AŞAĞIDAKİ ANOMALİLERDEN HANGİSİ MEYDANA GELİR.",
