    "subject": "Anatomi",
    "professor": "Mahmut Çay",
    "question": "El bileğinin üzerine düşme sonucu, bir kişinin karpal kemiklerinden, proksimal sırada lateral’den ikinci sırada yer alan kemik kırılmıştır. Kırılan kemik hangisidir?",
