    "professor": "Serçin Özlem Çalışkan",
    "question": "Aşağıda fotosensitizasyon ile ilgili verilen bilgilerden hangileri doğrudur?I.Yenidoğan sarılıklarında fototerapi için mavi ışık kullanılır.II.Psoralen ile etkileşime girmiş olan periferik kan mononükleer hücrelerinin ultraviyole A ile ışınlanması yöntemine PUVA denir.III.Oksijen fotodinamik tedavide değişken bir parametredir.IV.İdeal bir fotosensitif ajan sadece ışık altında aktive olmalıdır.V.Fotodinamik tedavi ile üretilen serbest oksijen radikallerinin başlangıç hedefi",
