    "open_answer": "",
    "explanation": "Manubrium sterni; üstte iki taraflı clavicula ile (incisura clavicularis), yanlarda 1. kaburga kıkırdağı ile ve angulus sterni hizasında **2. kaburga kıkırdağının üst yarısı ile** eklemleşir (1, 2 ve 3).",
