    "subject": "Anatomi",
    "professor": "Hülya Özdemir",
    "question": "1- Sternum; manubrium sterni, corpus sterni, ve processus xiphoideus olmak üzere 3 bölümden oluşur. 2- Sternumun en küçük ve çok varyasyon gösteren parçası corpus sternidir. 3- Kaburgaların önde kalan küçük kıkırdak kısmına cartilago costalis denir. 4- Kaburgalar arasında kalan aralığa spatium intercostale denir ve bir alttaki costanın numarası ile numaralandırılır. Yukarıda göğüs kemikleriyle ilgili bazı bilgiler verilmiştir. Hangisi ya da hangileri doğrudur?",
    "options": [
      {
        "letter": "A",
        "text": "1 ve 4"
      },
      {
        "letter": "B",
        "text": "1 ve 2"
      },
      {
        "letter": "C",
        "text": "1 ve 3"
      },
      {
        "letter": "D",
        "text": "1,3,4"
      },
      {
        "letter": "E",
        "text": "Hepsi"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "Sternum 3 parçadan oluşur (1) ve kaburgaların ön kıkırdak bölümü cartilago costalis'tir (3); sternumun en küçük parçası corpus değil proc. xiphoideus'tur; interkostal aralık ise üstteki kaburgaya göre adlandırılır.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": ""
