    "question": "Glukozun kullanılamadığı açlık ve diyabetes mellitus gibi durumlarda serbest yağ asitlerinin beta-oksidasyonu ile aşırı miktarda oluşan asetil-CoA’nın bir kısmı aşağıdakilerden hangisinin sentezinde kullanılır?",
