    "open_answer": "",
    "explanation": "Pre-embriyonik dönem (gelişimin ilk 2 haftası), ovumun döllenmesi (**fertilizasyon**) ile başlar ve blastokistin endometriuma tutunup **implantasyon** sürecini tamamlamasına kadar devam eder.",
