    "question": "Görüntüleme yöntemlerinde temel prensipler ile ilgili olarak eşleştirmelerden hangisi/hangileri yanlıştır?I.    Emisyon: Radyonüklid görüntülemedeII.   Transmisyon: Bilgisayarlı tomografiIII.  Emisyon: Röntgen IV.  Refleksiyon: Ultrason görüntülemeV.   Transmisyon:Manyetik rezonans görüntüleme",
