    "explanation": "Röntgen ve bilgisayarlı tomografi vücuttan geçen fotonların ölçüldüğü **transmisyon** tekniğidir; MRG ise protonların RF uyarımıyla sinyal yaydığı rezonans prensibidir (III ve V yanlış eşleştirilmiştir).",
