    "q_num": 89,
    "subject": "Tıp Tarihi ve Etik",
    "professor": "Tufan Mert",
    "question": "“Görüntü, x-ışını şiddet ölçümlerine dayalı olarak bilgisayarda yapılan hesaplamalarla oluşturulur. Vücuda değişik doğrultularda ince bir x-ışını gönderilerek, vücut içinde bulunan özel bir bölgenin veya bir hacim elementinin (voxel) x-ışını soğuruculuğu hakkında bilgi edinilir” şeklinde tanımlanan görüntüleme yönteminin adı nedir?",
    "options": [
      {
        "letter": "A",
        "text": "Fluoroskopi"
      },
      {
        "letter": "B",
        "text": "Angiografi"
      },
      {
        "letter": "C",
        "text": "Bilgisayarlı tomografi"
      },
      {
        "letter": "D",
        "text": "Manyetik rezonans görüntüleme"
      },
      {
        "letter": "E",
        "text": "Pozitron salma tomografisi-Öğrencinin işaretlediğ"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "**Bilgisayarlı tomografi** (BT), hastanın etrafında dönen X-ışını tüpünden gönderilen ince demetlerin dedektörlerle ölçülüp voksel atenüasyon değerlerinin bilgisayarda hesaplanmasıyla kesitsel görüntü oluşturur.",
