    "professor": "Soycan Mızrak",
    "question": "Ekstinksiyon katsayısı 14,3 olan ve 0,5 cm genişliğinde küvet kullanılarak 280 nm dalga boyunda ölçülen çözeltinin absorbansı 1,5 bulundu ise bu çözeltinin konsantrasyonu aşağıdakilerden hangisidir?",
