    "explanation": "**Merkel hücreleri**, derinin stratum basale tabakasında yer alan dokunma duyusu mekanoreseptörleri olup nöral krest/ektoderm kökenlidir; monosit-makrofaj fagositer sistem kökenli değildir.",
