    "explanation": "**Kortikal reaksiyon**, spermin oosit zarına tutunmasıyla oosit kortikal granüllerinin ekzositozla salınarak zona pellucidayı sertleştirmesi ve böylece **ikinci bir spermin girmesini (polispermiyi) önlemesidir**.",
    "note": "",
