    "professor": "Hatice Bozkurt Yavuz",
    "question": "Sentezi  K vitaminine bağımlı olan, 3 karboksiglutamat kalıntısı sayesinde, hidroksiapatit kristallerine afinitesi yüksek olan peptid aşağıdakilerden hangisidir?",
