    "professor": "Ayşe Özdemir",
    "question": "Sindirim sırasında safra kesesinin boşalması ile duodenuma akan safra asidleri pankreatik lipazı inaktive eder. Pankreas sıvısı içinde bulunan hangi maddde bu inaktivasyonu önler?",
