    "explanation": "**Kolipaz**, pankreastan prokolipaz olarak salgılanıp lümende tripsinle aktive edilir; safra tuzlarının lipazı inhibe etmesini önleyerek pankreatik lipazı lipid-su arayüzüne bağlar.",
