    "professor": "Ayşe Özdemir",
    "question": "\"12 C dan büyük yağ asitleri için Emilim duodenum ve jejenumda....................... ve ..........................kotransportla olur. Emilim öncesi 2. kez emülsifikasyon gerekir.\" Yukarıdaki boşluklara aşağıdakilerden hangisi gelmelidir?",
