    "professor": "Ayşe Özdemir",
    "question": "I) Prolin ve glisin bakımından çok zengindir. II) Yapısında hidroksilizin bulunmamaktadır. III) Glikozillenmemiştir. Yukarıdakilerden hangisi veya hangileri elastini kollajenden ayıran özelliklerindendir?",
