    "open_answer": "",
    "explanation": "**Elastik kıkırdak**, matrikste zengin elastik lif ağlarının yanı sıra hyalin kıkırdakta olduğu gibi **Tip II kollajen fibrillerini de** temel yapısal lif olarak içerir.",
    "note": "",
