    "open_answer": "",
    "explanation": "**Değişici epitel** (ürotelyum), idrar hacmine göre basıklaşıp gerilebilen ve idrar bariyeri oluşturan özelleşmiş epitelyum olup **üreteri** ve mesaneyi döşer.",
