    "explanation": "**Çok katlı prizmatik epitel**, tükürük bezlerinin büyük interlobüler boşaltım kanallarında, konjonktiva forniksinde ve erkek üretrasının bazı kısımlarında sınırlı olarak gözlenen epiteldir.",
