    "explanation": "**Mesane** (idrar torbası) lümeni, lümene bakan yüzeyinde gerilmeye uyum sağlayan şemsiye hücreleri içeren **değişici epitel** (transisyonel epitel / ürotelyum) ile döşelidir.",
