    "open_answer": "",
    "explanation": "Lenfoid organlar, kemik iliği ve karaciğerin narin destek çatısını oluşturan Tip III kollajen yapısındaki retiküler lifler **gümüşleme** yöntemiyle selektif olarak siyah boyanır.",
