    "explanation": "**Primordiyal germ hücreleri** (PGC), gelişimin 4. haftasında **vitellus kesesi duvarındaki** endoderm hücreleri arasından köken alarak ameboid hareketlerle dorsal mezenter boyunca genital çıkıntılara göç eder.",
