    "subject": "Histoloji ve Embriyoloji",
    "professor": "Gülsen Bayrak",
    "question": "I. Oosit matürasyon inhibitörü II. Sitostatik faktör III. Nöral apopitoz inhibitör protein (NAIP)Ovulasyon ile tamamlanan Mayoz 1’den sonra sekonder oositler Mayoz 2’nin metafaz evresinde beklerler. Sekonder Oositin Mayoz 2’nin metafaz evresinde kalmasını sağlayan faktör/ler yukarıdakilerden hangisi ya da hangileridir?",
