    "explanation": "İmplantasyon fertilizasyondan hemen sonra değil, **6. günde başlar** ve 1. haftada değil **2. haftanın sonunda (yaklaşık 11-12. günde)** endometriuma tamamen gömülerek tamamlanır.",
