    "professor": "Serçin Özlem Çalışkan",
    "question": "Bir radyasyon kaynağından belirli bir mesafede ölçülen doz hızı 640 mR/h ise doz hızını 20 mR/h değerine düşürmek için kaynakla detektör arasına kaç HVL (Yarı değer kalınlığı) konulması gerekir?",
    "options": [
      {
        "letter": "A",
        "text": "1 AB. AM İ N"
      },
      {
        "letter": "B",
        "text": "2"
      },
      {
        "letter": "C",
        "text": "3"
      },
      {
        "letter": "D",
        "text": "4"
      },
      {
        "letter": "E",
        "text": "5"
      }
    ],
    "answer": "E",
    "open_answer": "",
    "explanation": "Radyasyon dozunu 640 mR/h'den 20 mR/h değerine düşürmek için doz 640 / 20 = 32 kat azaltılmalıdır; 32 = 2^5 olduğundan araya tam **5 yarı değer kalınlığı (HVL)** zırh konulmalıdır.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
