    "open_answer": "",
    "explanation": "**Pozitif polariteli tek zincirli RNA virüslerinin** genomu konak hücre ribozomları tarafından doğrudan bir **mRNA molekülü** gibi tanınır ve hücreye girer girmez direkt protein translasyonunu başlatabilir.",
